  PRIMARY KEY (`id`),
  UNIQUE KEY `user_progress_user_id_course_id_lesson_id_key` (`user_id`,`course_id`,`lesson_id`),
  KEY `user_progress_user_id_idx` (`user_id`),
  KEY `user_progress_course_id_idx` (`course_id`),
